// Ноды Postgres отдают результат запроса, а не событие.
// Возвращаем исходное событие, чтобы маршрутизация работала с ним.
return [{ json: $('Событие от источника').first().json }];

// Ветка «эхо»: отдельный сценарий, не связанный с меню. Показывает, что
// ветвление добавляется нодой Switch без правки остального графа.
const ev = $json;
return [{
  json: {
    screen_key: 'echo',
    api_path: 'messages',
    api_query: { chat_id: String(ev.chat_id) },
    body: {
      text: '🔁 Вы написали: ' + ev.text.replace(/^эхо\s+/i, ''),
      format: 'markdown',
      attachments: [{ type: 'inline_keyboard', payload: {
        buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]] } }],
    },
  },
}];

// ЕДИНСТВЕННОЕ место, где описано меню бота.
// Чтобы поменять кнопки — правьте объект MENU прямо в редакторе n8n и нажмите
// Save. Рестарт контейнера не нужен, изменения подхватятся со следующего события.
//
// Типы кнопок MAX: callback | link | request_contact | request_geo_location |
//                  message | open_app | clipboard
const MENU = {
  main: {
    text: 'Привет, {name}! 👋\nЭто демо-бот, собранный целиком в n8n.\n\nВыберите раздел:',
    buttons: [
      [
        { type: 'callback', text: '📋 Каталог', payload: 'catalog' },
        { type: 'callback', text: 'ℹ️ О боте', payload: 'about' },
      ],
      [{ type: 'callback', text: '📞 Контакты', payload: 'contacts' }],
      [{ type: 'link', text: '🌐 Документация MAX', url: 'https://dev.max.ru/docs' }],
    ],
  },
  catalog: {
    text: '📋 *Каталог*\n\nВыберите товар:',
    buttons: [
      [
        { type: 'callback', text: 'Товар A — 100 ₽', payload: 'item:a' },
        { type: 'callback', text: 'Товар B — 250 ₽', payload: 'item:b' },
      ],
      [{ type: 'callback', text: '⬅️ Назад', payload: 'main' }],
    ],
  },
  about: {
    text: 'ℹ️ *О боте*\n\nСценарий целиком живёт в n8n: приём апдейтов MAX, разбор, меню и отправка ответов. Состояние — в Postgres.',
    buttons: [[{ type: 'callback', text: '⬅️ Назад', payload: 'main' }]],
  },
  contacts: {
    text: '📞 *Контакты*\n\nОставьте телефон, и мы перезвоним.',
    buttons: [
      [{ type: 'request_contact', text: '📱 Отправить контакт' }],
      [{ type: 'callback', text: '⬅️ Назад', payload: 'main' }],
    ],
  },
};

// Динамический экран: содержимое строится на лету из payload.
function screen(key) {
  if (key.startsWith('item:')) {
    const code = key.slice(5).toUpperCase();
    return {
      text: `✅ Товар *${code}* добавлен в корзину.\nВремя: ${new Date().toLocaleString('ru-RU', { timeZone: $env.TZ || 'Europe/Moscow' })}`,
      buttons: [[{ type: 'callback', text: '⬅️ В каталог', payload: 'catalog' }]],
    };
  }
  return MENU[key] ?? MENU.main;
}

const ev = $json;
const key = ev.kind === 'callback' ? (ev.payload || 'main') : 'main';
const scr = screen(key);

const body = {
  text: scr.text.replace('{name}', ev.name),
  format: 'markdown',
  attachments: [{ type: 'inline_keyboard', payload: { buttons: scr.buttons } }],
};

// Нажатие кнопки отвечаем через /answers — сообщение меняется на месте.
// Обычное сообщение отправляем через /messages.
if (ev.kind === 'callback' && ev.callback_id) {
  return [{ json: { screen_key: key, api_path: 'answers',
                    api_query: { callback_id: ev.callback_id },
                    body: { message: body } } }];
}
return [{ json: { screen_key: key, api_path: 'messages',
                  api_query: { chat_id: String(ev.chat_id) }, body } }];
